 void pinch(){ui(()->{MarketChart c=activity.chart;float center=c.getWidth()*.5f,y=c.getHeight()*.35f;MotionEvent.PointerProperties[] pp={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] pc={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){pp[i].id=i;pp[i].toolType=MotionEvent.TOOL_TYPE_FINGER;pc[i].y=y;pc[i].pressure=1;pc[i].size=1;}long now=SystemClock.uptimeMillis();for(int step=0;step<=10;step++){int count=step==0||step==10?1:2;int action=step==0?0:step==1?5|(1<<8):step==9?6|(1<<8):step==10?1:2;float span=activity.dp(80+step*24);pc[0].x=center-span/2;pc[1].x=center+span/2;MotionEvent e=MotionEvent.obtain(now,now+step*25,action,count,pp,pc,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);c.dispatchTouchEvent(e);e.recycle();}});}
