   File dir=new File(activity.getExternalFilesDir(null),f.shotFolder);dir.mkdirs();Files.write(new File(dir,"annotation-host-v64.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));
   SharedPreferences.Editor reset=settings.edit();if(hadAnnotations)reset.putBoolean("chartAnnotations",priorAnnotations);else reset.remove("chartAnnotations");if(hadLayout)reset.putString("layout",priorLayout);else reset.remove("layout");reset.commit();
