  ui(()->{MarketChart c=activity.chart;check(c.minute&&c.bars.size()==242&&c.count==count&&c.end==242,"fixed intraday never shrinks after pinch");check(Math.abs(c.barX(120)-c.barX(121))<.01f&&!Engine.valid(c.bars.get(80)),"lunch join and source gap preserved");});capture("minute-lunch-gap",true,false);rotate(true);capture("minute-lunch-gap",true,false);ui(()->{activity.onBackPressed();check(!activity.chartFullscreen.open()&&activity.findViewById(R.id.detail).isShown(),"first back returns to chart");activity.onBackPressed();check(activity.findViewById(R.id.home).isShown(),"next back returns home");});
